+      return null;
+    }
+
+    if (remainingCount > 0) {
+      return `오늘 남은 횟수(비회원): ${remainingCount}회`;
+    } else {
+      return "비회원 사용 한도를 전부 사용하셨습니다";
+    }
+  };
+  
+  const handlePrimaryButtonClick = () => {
+    setIsLoginModalOpen(false);
+    if (loginModalPurpose === 'limitReached') {
+      const newCount = 10;
+      setRemainingCount(newCount);
